<?php
declare(strict_types=1);
// Portfolio-only application. No CRM, customer portal, billing or order workflow.
function config():array {static $c;if($c===null){$p=__DIR__.'/config.php';if(!is_file($p))fail(503,'Сайт ещё не настроен.');$c=require $p;}return $c;}
function db():PDO {static $p;if(!$p){$c=config();$p=new PDO('mysql:host='.$c['db_host'].';port='.($c['db_port']??3306).';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$p->exec("SET time_zone='+00:00'");}return $p;}
function query(string $sql,array $args=[]):PDOStatement {$q=db()->prepare($sql);$q->execute($args);return $q;}
function security_headers():void {header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: no-referrer');header('X-Neurodelo-Site: portfolio-only');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: blob:; media-src 'self' blob:; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'");header('Cache-Control: no-store');}
function json_response(array $v,int $code=200):never {http_response_code($code);header('Content-Type: application/json; charset=utf-8');echo json_encode($v,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function fail(int $code,string $text):never {json_response(['detail'=>$text],$code);}
function same_origin():void {if(isset($_SERVER['HTTP_ORIGIN'])&&$_SERVER['HTTP_ORIGIN']!==rtrim(config()['app_url'],'/'))fail(403,'Недопустимый источник запроса.');if(($_SERVER['HTTP_SEC_FETCH_SITE']??'')==='cross-site')fail(403,'Недопустимый источник запроса.');}
function input():array {if((int)($_SERVER['CONTENT_LENGTH']??0)>65536)fail(413,'Слишком большой запрос.');if(stripos($_SERVER['CONTENT_TYPE']??'','application/json')!==0)fail(415,'Ожидается JSON.');$d=json_decode((string)file_get_contents('php://input',false,null,0,65537),true);if(!is_array($d))fail(400,'Некорректный запрос.');return $d;}
function text_field(array $d,string $key,int $max,bool $required=false):string {$v=$d[$key]??'';if(!is_string($v)||!mb_check_encoding($v,'UTF-8')||mb_strlen($v)>$max||($required&&trim($v)===''))fail(422,'Проверьте поле «'.$key.'».');return trim($v);}
function rate(string $kind,int $max):void {$bucket=hash('sha256',$kind.':'.($_SERVER['REMOTE_ADDR']??''));query('DELETE FROM nd_limits WHERE expires<=?',[time()]);query('INSERT INTO nd_limits(bucket,attempts,expires) VALUES (?,1,?) ON DUPLICATE KEY UPDATE attempts=attempts+1',[$bucket,time()+900]);if((int)query('SELECT attempts FROM nd_limits WHERE bucket=?',[$bucket])->fetchColumn()>$max){header('Retry-After: 900');fail(429,'Повторите попытку через 15 минут.');}}
function session_cookie(string $raw,int $until):void {setcookie('nd_session',$raw,['expires'=>$until,'path'=>'/','secure'=>parse_url(config()['app_url'],PHP_URL_SCHEME)==='https','httponly'=>true,'samesite'=>'Strict']);}
function current_session(bool $write=false):array {$raw=$_COOKIE['nd_session']??'';if(!is_string($raw)||!preg_match('/^[a-f0-9]{64}$/D',$raw))fail(401,'Войдите в кабинет портфолио.');$s=query('SELECT * FROM nd_sessions WHERE token=? AND expires>?',[hash('sha256',$raw),time()])->fetch();if(!$s)fail(401,'Войдите в кабинет портфолио.');if($write){same_origin();if(!hash_equals($s['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??''))fail(403,'Обновите страницу и повторите действие.');}return $s;}
function site_categories():array {return ['website'=>'Сайт','landing'=>'Лендинг','ai'=>'ИИ-агент','app'=>'Веб-приложение'];}
function site_record(int $id,bool $lock=false):array {$r=query("SELECT * FROM nd_publications WHERE id=? AND kind='portfolio'".($lock?' FOR UPDATE':''),[$id])->fetch();if(!$r)fail(404,'Работа не найдена.');return $r;}
function site_version(int $id):array {$r=query('SELECT * FROM nd_publication_versions WHERE id=?',[$id])->fetch();if(!$r||!hash_equals($r['checksum'],hash('sha256',$r['body_json'])))fail(404,'Редакция не найдена.');return json_decode($r['body_json'],true,512,JSON_THROW_ON_ERROR);}
function site_live(array $r):bool {if($r['state']!=='PUBLISHED'||!$r['published_version_id'])return false;if(!$r['order_id']||(site_version((int)$r['published_version_id'])['owner_rights_confirmed']??false)===true)return true;return (bool)query("SELECT g.id FROM nd_publication_permissions g JOIN nd_lc_document_bindings b ON b.id=g.binding_id JOIN nd_lc_templates t ON t.id=b.template_id WHERE g.version_id=? AND g.state='GRANTED' AND b.state='AGREED' AND b.order_id=? AND t.kind='portfolio_permission'",[$r['published_version_id'],$r['order_id']])->fetchColumn();}
function site_item(array $r,bool $owner=false):array {$vid=$owner?(int)query('SELECT id FROM nd_publication_versions WHERE publication_id=? AND revision_number=?',[$r['id'],$r['head_revision']])->fetchColumn():(int)$r['published_version_id'];$b=site_version($vid);if(!isset($b['cover']))foreach($b['media']??[] as $m)if((int)($b['cover_id']??0)===(int)$m['id']){$b['cover']=$m;break;}return ['id'=>(int)$r['id'],'slug'=>$r['slug'],'state'=>$r['state'],'version'=>(int)$r['version'],'body'=>$b];}
function site_storage():string {$p=__DIR__.'/publication-files';if(is_link($p)||(file_exists($p)&&!is_dir($p)))fail(503,'Хранилище недоступно.');if(!is_dir($p)&&!mkdir($p,0700))fail(503,'Хранилище недоступно.');return $p;}
function site_save(array $d):array {
    $title=text_field($d,'title',190,true);$text=text_field($d,'text',10000,true);$category=$d['category']??'website';if(!is_string($category)||!isset(site_categories()[$category]))fail(422,'Выберите категорию.');
    $url=text_field($d,'project_url',2000);if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_USER)!==null||parse_url($url,PHP_URL_PASS)!==null))fail(422,'Укажите публичную HTTPS-ссылку проекта.');
    $media=$d['media']??[];if(!is_array($media)||!array_is_list($media)||count($media)>500)fail(422,'Проверьте галерею.');$gallery=[];
    foreach($media as $m){if(!is_array($m)||!is_int($m['id']??null))fail(422,'Проверьте файл.');$f=query('SELECT * FROM nd_publication_media WHERE id=? AND deleted_at IS NULL AND purged_at IS NULL',[$m['id']])->fetch();if(!$f)fail(422,'Файл не найден.');$item=['id'=>(int)$f['id'],'mime'=>$f['mime'],'checksum'=>$f['checksum'],'caption'=>text_field($m,'caption',1000)];if($f['kind']==='external')$item['external_url']=$f['external_url'];$gallery[]=$item;}
    $cover=null;$coverId=$d['cover_id']??null;foreach($gallery as $m)if(str_starts_with($m['mime'],'image/')&&($coverId===null||(int)$coverId===$m['id'])){$cover=$m;break;}if($coverId!==null&&$cover===null)fail(422,'Выберите изображение из галереи для обложки.');
    $publish=($d['published']??false)===true;if($publish&&($d['rights_confirmed']??false)!==true)fail(422,'Подтвердите право публиковать материалы.');
    $body=['title'=>$title,'text'=>$text,'short_description'=>text_field($d,'short_description',1000),'category'=>$category,'project_url'=>$url,'task'=>text_field($d,'task',5000),'work'=>text_field($d,'work',5000),'result'=>text_field($d,'result',5000),'media'=>$gallery,'cover'=>$cover,'cover_id'=>$cover['id']??null,'featured'=>($d['featured']??false)===true,'owner_rights_confirmed'=>$publish];
    $p=db();$p->beginTransaction();try{
        $id=$d['id']??null;if($id!==null&&!is_int($id))fail(422,'Проверьте работу.');$r=$id?site_record($id,true):null;
        if($r&&(int)$r['version']!==($d['version']??null)){$p->rollBack();fail(409,'Работа уже изменена в другом окне. Откройте её заново.');}
        if(!$r){query("INSERT INTO nd_publications(kind,slug) VALUES ('portfolio',?)",['case-'.bin2hex(random_bytes(8))]);$id=(int)$p->lastInsertId();$r=site_record($id,true);}
        $n=(int)$r['head_revision']+1;$raw=json_encode($body,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);query('INSERT INTO nd_publication_versions(publication_id,revision_number,body_json,checksum) VALUES (?,?,?,?)',[$id,$n,$raw,hash('sha256',$raw)]);$vid=(int)$p->lastInsertId();
        // Existing customer grants stay immutable. Publishing an edited case is
        // an explicit owner publication, with rights confirmed outside the retired CRM.
        query('UPDATE nd_publications SET head_revision=?,state=?,published_version_id=?,version=version+1 WHERE id=?',[$n,$publish?'PUBLISHED':'DRAFT',$publish?$vid:null,$id]);
        $p->commit();return ['ok'=>true,'item'=>site_item(site_record($id),true)];
    }catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}
}
function site_upload():array {
    $f=$_FILES['file']??null;if(!is_array($f)||($f['error']??-1)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']))fail(422,'Файл не загружен. Проверьте лимит хостинга.');
    $size=filesize($f['tmp_name']);if(!$size||$size>8388608)fail(422,'Размер файла — до 8 МБ.');
    $name=basename((string)$f['name']);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$types=['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','mp4'=>'video/mp4','webm'=>'video/webm'];
    if(!isset($types[strtolower(pathinfo($name,PATHINFO_EXTENSION))])||$types[strtolower(pathinfo($name,PATHINFO_EXTENSION))]!==$mime)fail(422,'Выберите JPG, PNG, WebP, MP4 или WebM.');
    if((int)query('SELECT COALESCE(SUM(size_bytes),0) FROM nd_publication_media WHERE purged_at IS NULL')->fetchColumn()+$size>268435456)fail(422,'Медиатека заполнена (256 МБ).');
    if(str_starts_with($mime,'image/')&&!@getimagesize($f['tmp_name']))fail(422,'Изображение повреждено.');
    $key=bin2hex(random_bytes(32));$path=site_storage().'/'.$key;if(!move_uploaded_file($f['tmp_name'],$path))fail(503,'Не удалось сохранить файл.');chmod($path,0600);
    try{query('INSERT INTO nd_publication_media(storage_key,display_name,mime,size_bytes,checksum) VALUES (?,?,?,?,?)',[$key,mb_substr($name,0,190),$mime,$size,hash_file('sha256',$path)]);}catch(Throwable $e){unlink($path);throw $e;}
    return ['ok'=>true,'media'=>['id'=>(int)db()->lastInsertId(),'mime'=>$mime,'caption'=>'']];
}
